function surface(input) {
    // PMOVES joint coverage on the Poincare disk (2026-09-06 session).
    //
    // u = angle: the five INTEGRATION JOINTS where every defect this session
    //            appeared. A joint is a doc/contract owned by NEITHER side of
    //            a seam, which is why nothing watches it.
    // v = radius: distance from the watched middle. The living-docs ratchet
    //            tracks 33 docs clustered near the centre; all five joints sit
    //            out at the boundary, tracked by nothing.
    //
    // The Poincare boundary is infinitely far in the hyperbolic metric and
    // finite on screen -- which is the point. Drift at the rim is unbounded
    // and still renders as a thin edge you can miss.

    const theta = input.u * 2 * Math.PI;
    const r_raw = input.v * 0.95;
    const r = Math.tanh(r_raw * 2) * 0.95;

    const delta = input.delta || 0.5;     // ratchet coverage at this angle
    const kappa = input.kappa || -0.3;    // curvature: how fast drift compounds
    const hz    = input.hz    || 0.2;     // spectral entropy of the seam

    // Five joints. coverage = fraction the living-docs ratchet tracks.
    // Measured: branch-strategy 0, fork-sync 0, E2B 0, CHIT-specs 0, compose 0.
    const lobes = 5;
    const lobe = Math.cos(theta * lobes);

    // CONSUMPTION is the recurring defect: a field that satisfies its checker
    // and drives no decision. conf:0.95 hardcoded, Hg_traj unread, `sync`
    // ignored by fork_sync, required_status_checks.contexts empty.
    // Height ~ 0 means measured-but-unconsumed: present, flat, load-bearing
    // for nothing.
    const consumed = Math.max(0, lobe) * (1 - r);
    const z = consumed * 0.9 * Math.sin(theta * lobes);

    const x = r * Math.cos(theta);
    const y = r * Math.sin(theta);

    // Colour: green where a signal is both watched and consumed; red at the
    // rim where it is neither. The five joints are red by construction.
    const watched = consumed * (delta + 0.2);
    const red   = Math.max(0, 1 - watched * 2.2);
    const green = Math.min(1, watched * 2.2);
    const blue  = hz * 0.5 + (1 - r) * 0.15;

    return { x: x * 5, y: y * 5, z: z, r: red, g: green, b: blue, a: 0.85 };
}
